#!/bin/bash
# Print the top 3 IPs by frequency from access.log, ties broken by first appearance.
awk '
{
    ip = $1
    count[ip]++
    if (!(ip in order)) {
        order[ip] = ++n
    }
}
END {
    for (i = 1; i <= 3; i++) {
        best = ""
        for (ip in count) {
            if (seen[ip]) continue
            if (best == "" || count[ip] > count[best] ||
                (count[ip] == count[best] && order[ip] < order[best])) {
                best = ip
            }
        }
        print best
        seen[best] = 1
    }
}
' access.log
